%======================================================================
\section{Resistor network}

\subsection{4.1 Series combination}

Resistors are in \textbf{series} when the same current passes through each one in turn
(one path, no junction between them).

\begin{center}
\begin{circuitikz}[scale=1.05, transform shape]
  \draw (0,0) to[battery1, l=$V$] (0,2.2)
        to[R, l=$R_1$, v=$V_1$] (2.4,2.2)
        to[R, l=$R_2$, v=$V_2$] (4.8,2.2)
        -- (4.8,0) -- (0,0);
  \draw[-{Latex},thick] (0.35,1.8) -- (0.35,0.5)
    node[midway,left,font=\scriptsize] {$I$};
\end{circuitikz}
\end{center}

\begin{itemize}[leftmargin=1.4em,itemsep=0.12em,topsep=0.25em]
  \item \textbf{Same current:} $I_1=I_2=\cdots=I$ through every component in the chain.
  \item \textbf{p.d.s add:} the supply voltage is shared:
        $V=V_1+V_2+\cdots$.
  \item On each resistor, $V_k=IR_k$, so larger $R$ takes a larger share of $V$.
\end{itemize}

\formulabox{%
\textbf{Voltage division (series)}\\[0.2em]
$V_1:V_2=R_1:R_2$
\qquad
$V_1=V\dfrac{R_1}{R_1+R_2}$
\qquad
$V_2=V\dfrac{R_2}{R_1+R_2}$
}

\conceptcheck{%
  Two bulbs $X$ and $Y$ are connected in series to a cell. Bulb $X$ glows brighter than bulb $Y$.
  What happens if the positions of the bulbs are reversed?
  \begin{center}
  \begin{circuitikz}[scale=0.95, transform shape]
    \draw (0,0) to[battery1] (0,1.8)
          to[bulb, l=$X$] (2.2,1.8)
          to[bulb, l=$Y$] (4.4,1.8)
          -- (4.4,0) -- (0,0);
    \node[font=\scriptsize] at (2.2,-0.45) {before};
    \begin{scope}[xshift=5.8cm]
      \draw (0,0) to[battery1] (0,1.8)
            to[bulb, l=$Y$] (2.2,1.8)
            to[bulb, l=$X$] (4.4,1.8)
            -- (4.4,0) -- (0,0);
      \node[font=\scriptsize] at (2.2,-0.45) {positions reversed};
    \end{scope}
  \end{circuitikz}
  \end{center}
  \textbf{Amy:} Bulb $X$ will again glow brighter than bulb $Y$.\\
