\subsection{4.2 Parallel combination}

Resistors are in \textbf{parallel} when both ends of each branch connect the same two nodes
(same p.d.\ across every branch).

\begin{center}
\begin{circuitikz}[scale=1.05, transform shape]
  \draw (0,0.9) to[battery1, l_=$6\,\mathrm{V}$] (0,2.5);
  \draw (0,2.5) -- (0,3.4) -- (5.2,3.4);
  \draw (1.6,3.4) -- (1.6,2.7);
  \draw (3.8,3.4) -- (3.8,2.7);
  \draw (1.6,2.7) to[R, l=$3\,\Omega$, i=$I_1$] (1.6,0.7);
  \draw (3.8,2.7) to[R, l=$6\,\Omega$, i_=$I_2$] (3.8,0.7);
  \draw (1.6,0.7) -- (1.6,0) -- (5.2,0) -- (0,0) -- (0,0.9);
  \draw (3.8,0.7) -- (3.8,0);
  \draw[thick,red!75!black] (0,2.5) -- (0,3.4) -- (5.2,3.4);
  \draw[thick,red!75!black] (1.6,3.4) -- (1.6,2.7);
  \draw[thick,red!75!black] (3.8,3.4) -- (3.8,2.7);
  \draw[thick,blue!70!black] (1.6,0.7) -- (1.6,0) -- (5.2,0) -- (0,0) -- (0,0.9);
  \draw[thick,blue!70!black] (3.8,0.7) -- (3.8,0);
  \node[font=\scriptsize,red!75!black] at (2.6,3.65) {same potential ($6\,\mathrm{V}$)};
  \node[font=\scriptsize,blue!70!black] at (2.6,-0.4) {same potential ($0\,\mathrm{V}$)};
\end{circuitikz}
\end{center}

\begin{itemize}[leftmargin=1.4em,itemsep=0.12em,topsep=0.25em]
  \item \textbf{Same p.d.:} $V_1=V_2=\cdots=V$ across each branch.
  \item \textbf{Currents add:} $I=I_1+I_2+\cdots$ at a junction.
  \item On each branch, $I_k=V/R_k$, so smaller $R$ draws larger current.
\end{itemize}

\formulabox{%
\textbf{Current division (parallel)}\\[0.2em]
$I_1:I_2=\dfrac{1}{R_1}:\dfrac{1}{R_2}$
\qquad
$I_1=I\dfrac{R_{\mathrm{eq}}}{R_1}$
\qquad
(two resistors: $I_1=I\dfrac{R_2}{R_1+R_2}$)
}

\conceptcheck{%
