  \node[circ] at (4.0,-0.5) {};
  \node[font=\scriptsize,right] at (4.15,-0.5) {$B$};
  \node[ground] at (4.8,-0.5) {};
  \draw (4.0,-0.5) -- (4.8,-0.5);
\end{circuitikz}
\end{center}
Every resistor is $2\,\Omega$. $B$ is earthed. With the switch closed, find the potential at $A$.
\sol{%
Colour: red $=6\,\mathrm{V}$, green $=V_A$, blue $=0\,\mathrm{V}$.
Parallel pair both red$\to$green: same p.d.\ $V_L=6-V_A$.
Each carries $V_L/2$; junction at $A$ gives $V_L/2+V_L/2=V_A/2$, so $V_L=V_A/2$.
Hence $6-V_A=V_A/2\Rightarrow V_A=4\,\mathrm{V}$.
}

\subsection{Series and parallel combinations}

\begin{center}
\begin{tabular}{@{}p{0.46\textwidth}p{0.46\textwidth}@{}}
\toprule
\textbf{Series} & \textbf{Parallel} \\
\midrule
Same current: $I_1=I_2=\cdots$
&
Same p.d.: $V_1=V_2=\cdots$
\\[0.3em]
p.d.s add: $\mathcal{E}=V_1+V_2+\cdots$
&
Currents add: $I=I_1+I_2+\cdots$
\\[0.3em]
$R_{\mathrm{eq}}=R_1+R_2+\cdots$
&
$\displaystyle\frac{1}{R_{\mathrm{eq}}}=\frac{1}{R_1}+\frac{1}{R_2}+\cdots$
\\[0.5em]
If $R_1=R_2=R$, then $R_{\mathrm{eq}}=2R$.
&
If $R_1=R_2=R$, then $R_{\mathrm{eq}}=R/2$.
\\
\bottomrule
\end{tabular}
\end{center}

\begin{center}
\begin{circuitikz}[scale=1.0, transform shape]
  % series: terminals A, B
  \draw (0,0) node[ocirc]{} node[left,font=\scriptsize] {$A$}
        to[R, l=$R_1$] (2.2,0)
        to[R, l=$R_2$] (4.4,0)
        node[ocirc]{} node[right,font=\scriptsize] {$B$};
  \node[font=\scriptsize] at (2.2,-0.75) {series};
  % parallel: terminals A, B (rectangular)
  \draw (6.0,0) node[ocirc]{} node[left,font=\scriptsize] {$A$}
        -- (6.5,0) -- (6.5,1.0)
        to[R, l=$R_1$] (8.7,1.0)
        -- (8.7,0) -- (9.2,0)
        node[ocirc]{} node[right,font=\scriptsize] {$B$};
  \draw (6.5,0) -- (6.5,-1.0)
        to[R, l_=$R_2$] (8.7,-1.0)
        -- (8.7,0);
  \node[font=\scriptsize] at (7.6,-2.15) {parallel};
\end{circuitikz}
\end{center}

\conceptcheck{%
  T/F: three equal resistors $R$ in parallel have equivalent resistance $R/3$.}
% answer: True (1/Req = 3/R => Req = R/3)

\ex
A $12\,\mathrm{V}$ cell of negligible internal resistance feeds the network shown.
\begin{center}
\begin{circuitikz}[scale=1.05, transform shape]
  \draw (0,0) to[battery1, l=$12\,\mathrm{V}$] (0,2)
        to[R, l=$8\,\Omega$] (3,2)
        to[short, *-] (3,3)
        to[R, l=$6\,\Omega$] (5.5,3)
        to[short, -*] (5.5,2)
        -- (5.5,0) -- (0,0);
  \draw (3,2) to[short, *-] (3,1)
        to[R, l_=$12\,\Omega$] (5.5,1)
        to[short, -*] (5.5,2);
\end{circuitikz}
\end{center}
Find all branch currents and voltages.
\sol[3.8cm]{%
\[
R_{\parallel}=\Bigl(\frac{1}{6}+\frac{1}{12}\Bigr)^{-1}=4\,\Omega,\qquad
R_{\mathrm{eq}}=8+4=12\,\Omega,\qquad
I=\frac{12}{12}=1.0\,\mathrm{A}.
\]
$I_8=1.0\,\mathrm{A}$, $V_8=8\,\mathrm{V}$. Parallel p.d.\ $V_6=V_{12}=4\,\mathrm{V}$.
$I_6=4/6=0.67\,\mathrm{A}$, $I_{12}=4/12=0.33\,\mathrm{A}$.
}
\worked{2012}{26}{B}{58}{../questions/2012_q26.png}{%
Top network equivalent $R_{\mathrm{u}}$ is in parallel with the bottom $12\,\Omega$.
Given $R_{ab}=6\,\Omega$:
$\frac{1}{6}=\frac{1}{R_{\mathrm{u}}}+\frac{1}{12}\Rightarrow R_{\mathrm{u}}=12\,\Omega$.
Replace $12\,\Omega$ by $6\,\Omega$:
$\frac{1}{R'}=\frac{1}{12}+\frac{1}{6}=\frac{1}{4}\Rightarrow R'=4\,\Omega$ $\Rightarrow$ \textbf{B}.}

\worked{2013}{30}{B}{40}{../questions/2013_q30.png}{%
Identical resistors: $Y\parallel Z$ gives $R/2$, then series with $X$: $R_{\mathrm{eq}}=\tfrac{3}{2}R$.
Total power $24\,\mathrm{W}$. Voltage across the parallel pair is $V/3$, so
$P_Z=(V/3)^{2}/R$. With $V^{2}/R=24\cdot\tfrac{3}{2}=36$, get $P_Z=4\,\mathrm{W}$ $\Rightarrow$ \textbf{B}.}

\subsection{Combine, then split (standard method)}

\ex
Two $4\,\Omega$ in parallel, then series with $2\,\Omega$, across $9\,\mathrm{V}$ ideal.
\begin{enumerate}
  \item Find $R_{\mathrm{eq}}$.
  \item Find the cell current.
  \item Find the current in one $4\,\Omega$.
  \item Find the power in the $2\,\Omega$.
\end{enumerate}
\sol[3.5cm]{%
\begin{enumerate}
  \item $R_{\parallel}=2\,\Omega$, $R_{\mathrm{eq}}=4\,\Omega$.
  \item $I=9/4=2.25\,\mathrm{A}$.
  \item Equal parallel pair: each $1.125\,\mathrm{A}$.
  \item $P_{2}=I^{2}R=(2.25)^{2}(2)=10.1\,\mathrm{W}$.
\end{enumerate}
}

\subsection{Identical-resistor networks}

\begin{itemize}[leftmargin=1.2em,itemsep=0.12em,topsep=0.25em]
  \item Redraw: mark equipotential wires, then collapse series and parallel blocks.
  \item Equal parallel branches often carry equal currents; the cell current is the sum.
  \item A switch shorting a branch forces $V=0$ across that branch; recompute $R_{\mathrm{eq}}$.
  \item Burnt filament $=$ open branch: remove it, then find the new equivalent resistance.
  \item At every junction: total current in $=$ total current out.
\end{itemize}

\ex
All resistors identical. The ammeter in the left parallel branch reads $1.0\,\mathrm{A}$.
\begin{center}
\begin{circuitikz}[scale=1.0, transform shape]
  \draw (0,0) to[battery1] (0,2.4)
        -- (2.0,2.4)
        to[R, l=$r$] (4.2,2.4)
        -- (4.2,0) -- (0,0);
  \draw (2.0,2.4) -- (2.0,1.2)
        to[ammeter, l=$1.0\,\mathrm{A}$] (4.2,1.2)
        -- (4.2,2.4);
\end{circuitikz}
\end{center}
Find the current through the battery.
\sol[2.5cm]{%
Two equal parallel resistors: same $V$, same $I=1.0\,\mathrm{A}$ each.
Battery current $I=1.0+1.0=2.0\,\mathrm{A}$.
}

\ex
\begin{center}
\begin{circuitikz}[scale=1.0, transform shape]
  \draw (0,0) to[battery1, l=$1\,\mathrm{V}$] (0,2.2)
        to[ammeter, l=$A$] (2.0,2.2)
        -- (2.0,2.8) to[R, l=$1\,\Omega$] (4.2,2.8) -- (4.2,0) -- (0,0);
  \draw (2.0,2.2) -- (2.0,1.0) to[R, l_=$1\,\Omega$] (4.2,1.0) -- (4.2,0);
\end{circuitikz}
\end{center}
Find the ammeter reading. (Third identical resistor arrangements are similar: reduce first.)
\sol[2.5cm]{%
The two $1\,\Omega$ are in parallel: $R_{\mathrm{eq}}=0.5\,\Omega$.
$I=1/0.5=2.0\,\mathrm{A}$.
}

\subsection{Voltage dividers and opposing cells}

Series chain $R_1,R_2,\ldots$ across $V$:
$V_k=V\cdot R_k/R_{\mathrm{eq}}$.

\ex
$6\,\mathrm{V}$ and $12\,\mathrm{V}$ cells oppose through $2\,\Omega$ and $4\,\Omega$ in series.
Find $V_{PQ}$ between the mid-junctions of the two branches.
\sol[2.8cm]{%
Net e.m.f.\ $|12-6|=6\,\mathrm{V}$, $R_{\mathrm{eq}}=6\,\Omega$, $I=1\,\mathrm{A}$.
Then $V_{PQ}$ from drops around either path: often $0\,\mathrm{V}$ if the mid-points sit at the
same potential.
}

\subsection{Variable resistor effects}

Increasing a series rheostat: total $R\uparrow\Rightarrow I\downarrow$ (ammeter falls).
Voltmeter across the \emph{fixed} load usually falls; across the rheostat usually rises
(larger share of $\mathcal{E}$).
Increasing $R$ in parallel with a bulb often makes that bulb brighter (less current stolen) while
total cell current may fall.

